using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using System.Linq;
using System.Text;
using ConRoi.Investigation.V36.R103;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            s.OpenPage("conclusions");
            var w = EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));
            Action<float, float> click = (x, y) =>
            {
                var p = new Vector2(x * Screen.width / 1200 / 1.25f, y * Screen.height / 800 / 1.25f + 55);
                w.SendEvent(new Event{type = EventType.MouseDown, button = 0, mousePosition = p});
                w.SendEvent(new Event{type = EventType.MouseUp, button = 0, mousePosition = p});
            };
            var log = new StringBuilder("Synthetic mouse UI consent/save and three sidebar reloads, own ui-profile only.\n");
            var pos = s.movement.transform.position;
            int i = 0;
            double next = EditorApplication.timeSinceStartup + .7;
            EditorApplication.CallbackFunction f = null;
            f = () =>
            {
                if (EditorApplication.timeSinceStartup < next)
                    return;
                next = EditorApplication.timeSinceStartup + .7;
                try
                {
                    switch (i++)
                    {
                        case 0:
                            click(650, 482);
                            break;
                        case 1:
                            ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r103/conclusion-ui-confirmed.png");
                            break;
                        case 2:
                            click(650, 523);
                            break;
                        case 3:
                            if (!s.data.finalized || s.data.conclusions.Any(c => c.choice != 0))
                                throw new Exception("UI conclusion save failed");
                            log.AppendLine("PASS UI saved insufficient with claim=" + s.data.conclusions[0].claim);
                            ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r103/conclusion-ui-final.png");
                            break;
                        case 4:
                        case 5:
                        case 6:
                            click(120, 365);
                            break;
                        default:
                            if (!s.data.finalized || s.Page != "conclusions" || Vector3.Distance(pos, s.movement.transform.position) > .0001f)
                                throw new Exception("Reload changed conclusion/page/player");
                            log.AppendLine("PASS three UI reloads retain claim, page and position");
                            File.WriteAllText("Test/KetQua/investigation_r103/conclusion-ui.txt", log.ToString());
                            EditorApplication.update -= f;
                            break;
                    }
                }
                catch (Exception e)
                {
                    EditorApplication.update -= f;
                    File.WriteAllText("Test/KetQua/investigation_r103/conclusion-ui.txt", log + "FAIL " + e);
                }
            };
            EditorApplication.update += f;
            r.Log("Final UI consent/save/reload check");
        }
    }
}

